// Command mellifera is the composition root: a flat, top-to-bottom constructor
// list that wires the whole app graph in one file. It reads configuration from
// the environment, opens the store, loads and starts the base-scanner +
// serial-scanner (scanner) and tv-parser + image-enricher + serial-parser +
// frame-grabber + shikimori (metadata_source) plugin subprocesses, constructs
// enrich.Deps and wires it into the scan orchestrator, assembles the HTTP
// edge, and serves until SIGINT/SIGTERM. There is no DI container and no
// reflection wiring — every dependency is an explicit constructor call
// (ai-architecture §2 principle 5; mellifera-build skill; depguard denies
// reflect + DI frameworks).
//
// Dev-mode plugin loading: each plugin binary is loaded from a configurable
// filesystem path (env MELLIFERA_BASE_SCANNER / MELLIFERA_SERIAL_SCANNER /
// MELLIFERA_TV_PARSER / MELLIFERA_IMAGE_ENRICHER / MELLIFERA_SERIAL_PARSER /
// MELLIFERA_FRAME_GRABBER / MELLIFERA_SHIKIMORI, defaults bin/base-scanner /
// bin/serial-scanner / bin/tv-parser / bin/image-enricher / bin/serial-parser /
// bin/frame-grabber / bin/shikimori from `make build-plugin`). go:embed
// first-run extraction is deferred to release packaging (D11/Q20).
package main

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strconv"
	"sync"
	"syscall"
	"time"

	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/plugin"
	"github.com/mellifera/mellifera/internal/scan"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
	"github.com/mellifera/mellifera/internal/web"
	"github.com/mellifera/mellifera/pkg/sdk"
)

// Launch-consent + identity constants shared with the plugin subprocess. The
// magic-cookie pair MUST match the values base-scanner, tv-parser, AND
// image-enricher validate
// (MELLIFERA_MAGIC_COOKIE / mellifera-plugin-v1); a mismatch is a fatal
// substrate-handshake failure. coreVersion mirrors the plugins' min_core.
const (
	magicCookieKey   = "MELLIFERA_MAGIC_COOKIE"
	magicCookieValue = "mellifera-plugin-v1"
	coreVersion      = "0.1.0"
	scannerService   = "mellifera.scanner.v1.Scanner"
	metadataService  = "mellifera.metadata.v1.MetadataSource"
)

// Lifecycle timeouts: a bounded read-header window (slowloris protection) and a
// best-effort graceful-shutdown budget. The plugin subprocess has its own
// SIGTERM grace (plugin.Manager.Stop), independent of this budget.
const (
	readHeaderTimeout = 10 * time.Second
	shutdownTimeout   = 15 * time.Second
)

func main() {
	cfg := loadConfig()

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	// --- wiring: flat constructor list, the whole app graph in order ---
	st, err := store.Open(ctx, cfg.dsn)
	fatalOn(err, "open store")
	defer st.Close()

	reg, err := module.Open(ctx, st)
	fatalOn(err, "open module registry")

	mgr := plugin.Open(plugin.Deps{
		MagicCookieKey:   magicCookieKey,
		MagicCookieValue: magicCookieValue,
		CoreVersion:      coreVersion,
	})
	// sourceCatalog is the boot-literal plugin inventory table (plugin-title-
	// enrichment D6): every plugin the Manager loads below, with its
	// operator-facing display name and one-line description for the
	// GET /admin/sources aggregate. The single source for BOTH the pluginIDs
	// load/status set (derived below) and the Deps.SourceInventory closure —
	// a plugin added to the load list is added here once. A Phase-2+
	// Manager.List() would replace the id half (INV-known-plugin-set).
	type catalogEntry struct {
		id, name, description string
	}
	sourceCatalog := []catalogEntry{
		{"base-scanner", "Base Scanner", "Directory scanner for tv and image libraries."},
		{"serial-scanner", "Serial Scanner", "Structure-aware directory scanner for serial libraries."},
		{"tv-parser", "TV Parser", "Local filename parser for tv episodes."},
		{"image-enricher", "Image Enricher", "Local EXIF metadata enrichment for images."},
		{"serial-parser", "Serial Parser", "Local directory-facts parser for serials."},
		{"frame-grabber", "Frame Grabber", "ffmpeg thumbnail and frame metadata for serial episodes."},
		{"shikimori", "Shikimori", "External Shikimori metadata enrichment for serials."},
	}
	// pluginIDs is the canonical set of plugin IDs loaded + started below AND
	// iterated by the Deps.Status closure — derived from sourceCatalog so the
	// load sites, the status closure, and the admin-sources inventory cannot
	// diverge.
	pluginIDs := make([]string, len(sourceCatalog))
	for i, p := range sourceCatalog {
		pluginIDs[i] = p.id
	}
	// loadedCaps is each loaded plugin's declared capability TYPES, captured at
	// its Load site — the Deps.PluginCapabilities closure's validation set
	// (element-pages 3.1/3.3). Derived from the same []sdk.Capability literals
	// the Manager.Load calls carry, so the declaration has one source: a plugin
	// added to the load list (an anitomy, when it lands) is validated-attachable
	// with no second place to update.
	loadedCaps := map[string][]string{}
	// loadPlugin registers one plugin binary + its capability declaration and
	// starts the subprocess — the flat per-plugin Load+Start pair, factored so
	// loadedCaps is captured at the declaration site. fatalOn keeps the
	// fail-fast startup posture of the calls it replaces.
	loadPlugin := func(pluginID, binaryPath string, caps []sdk.Capability) {
		fatalOn(mgr.Load(pluginID, binaryPath, caps), "load "+pluginID)
		fatalOn(mgr.Start(ctx, pluginID), "start "+pluginID)
		types := make([]string, 0, len(caps))
		for _, c := range caps {
			types = append(types, c.Type)
		}
		loadedCaps[pluginID] = types
	}

	// base-scanner is the tv/image scanner plugin.
	loadPlugin("base-scanner", cfg.baseScannerPath, []sdk.Capability{
		{Type: "scanner", ID: "default", ProtoService: scannerService},
	})

	// serial-scanner is the second scanner-capability plugin (serials-library
	// D2): directory-structured discovery, selected purely by module config
	// (the structure knob). Same dev-mode pattern + cookie pair as
	// base-scanner.
	loadPlugin("serial-scanner", cfg.serialScannerPath, []sdk.Capability{
		{Type: "scanner", ID: "default", ProtoService: scannerService},
	})

	// tv-parser is the first metadata_source plugin (parseTV extracted from
	// base-scanner in T06/T07). It loads from a filesystem path with the same
	// dev-mode pattern + cookie pair as base-scanner; its capability declaration
	// matches the plugin's Handshake (T06).
	loadPlugin("tv-parser", cfg.tvParserPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	// image-enricher is the image metadata_source plugin (EXIF via the system
	// exiftool subprocess — Task 01). Same dev-mode pattern + cookie pair +
	// capability declaration as tv-parser. Started BEFORE the server serves
	// (INV-start-before-serve) so the first image scan's B1 queue finds a
	// live enricher.
	loadPlugin("image-enricher", cfg.imageEnricherPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	// serial-parser + frame-grabber are the serials-module metadata_source
	// chain (serials-library D3/D5): the local directory-facts parser
	// (priority 1) and the ffmpeg frame-grab default images (priority 2). Same
	// dev-mode pattern + cookie pair + capability declaration as tv-parser.
	loadPlugin("serial-parser", cfg.serialParserPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})
	loadPlugin("frame-grabber", cfg.frameGrabberPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	// shikimori is the first EXTERNAL metadata_source (enrichment: the
	// serials-module chain's priority-3 slot, priority set by the module seed).
	// Its outbound fetches are paced by the enrich FetchGate constructed below
	// (the request spec's min_interval_ms is enforced core-side, enrichment
	// D-5). Same dev-mode pattern + cookie pair + capability declaration as
	// the other metadata plugins.
	loadPlugin("shikimori", cfg.shikimoriPath, []sdk.Capability{
		{Type: "metadata_source", ID: "default", ProtoService: metadataService},
	})

	scanDeps := scan.Deps{
		Store:   st,
		Modules: reg,
		Plugins: mgr,
		// FetchGate (enrichment D-5 — box 2.2's injection point): the
		// per-plugin outbound pacing gate, constructed on the real clock here
		// in the composition root and injected into the enrich chain; nil
		// would mean unpaced.
		Enrich: enrich.Deps{Store: st, Modules: reg, Plugins: mgr, FetchGate: enrich.NewFetchGate()},
	}

	// Packaged-playback pack lane (D-3/D-4/D-5): the enrich queue's PackItem
	// seam closes over the stream Service (Interface 2 — enrich never imports
	// stream; this closure is the only bridge). The artifact root lives inside
	// the server's own data space, never a library directory.
	mediaSvc := &stream.Service{
		Root:     cfg.streamsRoot,
		Secret:   cfg.mediaSecret,
		Original: originalResolver(st),
	}
	scanDeps.Enrich.PackItem = func(ctx context.Context, itemID, absPath string, ffprobe map[string]any, voiceovers []string) (enrich.PackOutcome, error) {
		build, err := mediaSvc.Pack(ctx, itemID, absPath, ffprobe, voiceovers)
		return enrich.PackOutcome{Playlist: build.Playlist, Nonce: build.Nonce}, err
	}
	// Async enrich queue (arch §4.4): a bounded worker pool that derives pending
	// (item, plugin) work from items + the ledger and drains it for the process
	// lifetime. Constructed + started BEFORE the server serves so the first
	// scan's Notify lands in a running pool (INV-start-before-serve). Flat
	// constructor call — no DI, no reflect (INV-flat-wiring).
	enrichQueue := enrich.NewQueue(scanDeps.Enrich, cfg.enrich)
	fatalOn(enrichQueue.Start(ctx), "start enrich queue")
	// scan hands the library to the queue after persisting items pending. The
	// closure substitutes the PROCESS ctx (not the per-request scan ctx) so the
	// queue's derive/feeder outlives the HTTP request — otherwise the feeder
	// would abort the moment the scan handler returns and never drain
	// (INV-context-shared: SIGINT/SIGTERM cancels pool + server together).
	scanDeps.Notify = func(_ context.Context, libraryID int64) {
		enrichQueue.Notify(ctx, libraryID)
	}
	// Deps.Status closure (arch §4.4 best-effort liveness; INV2 anti-corruption
	// seam — built HERE in cmd/mellifera so api imports neither plugin nor
	// enrich, mirroring the Deps.Scan func-field above). Iterates the canonical
	// pluginIDs set, maps plugin.Health→api.PluginHealth (RFC3339 at the edge —
	// INV-time-format-at-edge), and reads enrichQueue.Stats()→api.EnrichStats.
	// A per-plugin Status error omits that one entry but does NOT fail the whole
	// snapshot (B3 best-effort) — it returns the healthy plugins + the enrich
	// snapshot rather than 500ing /admin/status over one bad plugin.
	statusClosure := func(ctx context.Context) (api.AdminStatus, error) {
		plugins := make([]api.PluginHealth, 0, len(pluginIDs))
		for _, id := range pluginIDs {
			h, err := mgr.Status(id)
			if err != nil {
				slog.Warn("admin status: plugin status unavailable", "plugin", id, "error", err)
				continue
			}
			checkedAt := ""
			if !h.LastCheckedAt.IsZero() {
				checkedAt = h.LastCheckedAt.Format(time.RFC3339)
			}
			plugins = append(plugins, api.PluginHealth{
				ID:        id,
				State:     h.State,
				Message:   h.Message,
				Restarts:  h.Restarts,
				CheckedAt: checkedAt,
			})
		}
		es := enrichQueue.Stats()
		return api.AdminStatus{
			Plugins: plugins,
			Enrich: api.EnrichStats{
				Pending:  es.Pending,
				InFlight: es.InFlight,
				Done:     es.Done,
				Failed:   es.Failed,
			},
		}, nil
	}

	// sweeps is the per-library whole-sweep in-flight guard the Reenrich
	// closure owns (enrichment design Interfaces): one slot per library, held
	// for the whole-library sweep's duration. Process-lifetime state by design
	// — the guarded span (strip pass + Notify) is synchronous inside
	// Queue.ReenrichSource.
	sweeps := &sweepGuard{inFlight: map[int64]bool{}}

	apiHandler := api.New(api.Deps{
		AdminToken: cfg.adminToken,
		Store:      st,
		Scan: func(ctx context.Context, libraryID int64) (scan.Result, error) {
			return scan.Run(ctx, scanDeps, libraryID)
		},
		Status: statusClosure,
		// Playback descriptor (D-7): pure delegation over the stream Service's
		// Describe + a fresh media token (the anti-corruption seam keeps api
		// free of a stream import, mirroring Status above).
		Playback: func(ctx context.Context, itemID string) (api.Playback, error) {
			row, err := st.GetItem(ctx, itemID)
			if err != nil {
				return api.Playback{}, err // sql.ErrNoRows → 404 at the handler
			}
			var doc map[string]any
			if err := json.Unmarshal(row.Document, &doc); err != nil {
				return api.Playback{}, err
			}
			mode, state, playURL, sections, voiceovers := mediaSvc.Describe(itemID, doc)
			token, _ := mediaSvc.Issue(itemID, time.Now()) // cookie-primary delivery
			return api.Playback{
				Mode:       mode,
				State:      state,
				PlayURL:    playURL,
				Sections:   sections,
				Voiceovers: voiceovers,
				Token:      token,
			}, nil
		},
		// Play verb (D-7 — the ONLY playback mutation): retry re-enqueues a
		// failed packaging run through the streams lane; fromSeconds is
		// reserved (a v1 no-op carried through). The failed check reads the
		// item's stored streams namespace — the lane is its only writer.
		Play: func(ctx context.Context, itemID string, retry bool, _ *float64) (bool, error) {
			row, err := st.GetItem(ctx, itemID)
			if err != nil {
				return false, err // sql.ErrNoRows → 404 at the handler
			}
			if !retry {
				// Pack-on-play (D-8): the played item (a movie the frontier
				// never fronts, or any unpackaged packable item) gets its
				// packaging enqueued by the play that asked for it; the
				// direct floor answers everything else. queued=true → 202.
				return packOnPlay(ctx, st, enrichQueue.EnqueuePack, row)
			}
			var doc map[string]any
			if err := json.Unmarshal(row.Document, &doc); err != nil {
				return false, err
			}
			streams, _ := doc["streams"].(map[string]any)
			state, _ := streams["state"].(string)
			if state != stream.StateFailed {
				return false, nil // nothing failed → 400 nothing_failed at the handler
			}
			if err := enrichQueue.EnqueuePack(itemID); err != nil {
				return false, err
			}
			return true, nil // 202 accepted
		},
		// Stop-frame re-grab (continue-nextup-media D-1..D-4): the watch-event
		// seam — a per-item debounced, request-detached re-grab of the
		// frame-grabber thumbnail at the viewer's stop position. The JPEG
		// overwrites the same deterministic path, so there is NO document
		// write and NO enrich round-trip (grabbed_at stays stale by design);
		// every executor failure is log-and-skip — progress is never
		// load-bearing and the PUT response never carries it.
		OnProgress: newThumbRegrab(st, mgr),
		// Module presentation (element-pages 3.4/3.1; widened per
		// plugin-title-enrichment D5): the library-surface block —
		// identity_fields plus the ordered parser bindings (scanner slot, then
		// the metadata_source chain in config order) with their capability ids
		// and display_fields declarations, and the title-walk inputs: ONE
		// batched prefs read for THIS library (module-scope rows + its own;
		// store.ListMetadataSourcePrefs) resolved through enrich.ResolveGates
		// (inherit-then-override; a muted source carries Enabled=false, which
		// the composer skips) and projected in the config's
		// title_source_priority order — plus language_preference verbatim.
		// Built over the module registry and the store (INV2: api imports
		// neither); slices are copied defensively so the handler can never
		// alias cached registry state.
		ModulePresentation: func(ctx context.Context, moduleID string, libraryID int64) (api.ModulePresentation, error) {
			m, err := reg.Get(moduleID)
			if err != nil {
				return api.ModulePresentation{}, err
			}
			parsers := make([]api.ParserBinding, 0, 1+len(m.MetadataSources))
			parsers = append(parsers, api.ParserBinding{
				ID:            m.Scanner.PluginID,
				Capability:    m.Scanner.CapabilityID,
				DisplayFields: copyStrings(m.Scanner.DisplayFields),
			})
			for _, src := range m.MetadataSources {
				parsers = append(parsers, api.ParserBinding{
					ID:            src.PluginID,
					Capability:    src.CapabilityID,
					DisplayFields: copyStrings(src.DisplayFields),
				})
			}
			prefs, err := st.ListMetadataSourcePrefs(ctx, moduleID, []int64{libraryID})
			if err != nil {
				return api.ModulePresentation{}, err
			}
			gated := enrich.ResolveGates(m, prefs, libraryID)
			byID := make(map[string]module.MetadataSourceBinding, len(gated))
			for _, src := range gated {
				byID[src.PluginID] = src
			}
			pres := api.ModulePresentation{
				IdentityFields: copyStrings(m.IdentityFields),
				Parsers:        parsers,
				// Module default element template (display-naming 3.3): the
				// composition floor under a library's own naming_element_name
				// option — namerFor layers the library option OVER this.
				ItemName:           m.ItemName,
				LanguagePreference: copyStrings(m.LanguagePreference),
			}
			for _, id := range m.TitleSourcePriority {
				src, ok := byID[id]
				if !ok {
					continue // a priority id with no modeled binding is config drift — skip it silently
				}
				pres.AddTitleSource(id, src.Enabled)
				// refresh_sources (plugin-admin-surfaces D1): the same walk,
				// filtered to modeled bindings whose plugin is loaded
				// (loadedCaps) and whose effective gate resolution is enabled
				// — config order, the refresh pickers' option list. A muted
				// source is never revived here: Enabled is the ResolveGates
				// verdict (a gate mutes, never revives), so the served list
				// carries only effectively-enabled entries.
				if _, loaded := loadedCaps[id]; loaded && src.Enabled {
					pres.AddRefreshSource(id, src.Enabled)
				}
			}
			// source_chain (media-data-convention D6, additive): every bound
			// metadata source in CHAIN order — m.MetadataSources order, which
			// enrich.ResolveGates preserves — each carrying its gate-resolved
			// enabled verdict. Unlike the filtered refresh list, a muted
			// source is carried WITH enabled=false: the api convention
			// projection walks this list as the served resolution order and
			// must see the mute to skip the source. Deliberately not the
			// title_source_priority walk above — that order is the title
			// machine's, not the chain's.
			for _, src := range gated {
				pres.AddChainSource(src.PluginID, src.Enabled)
			}
			return pres, nil
		},
		// Admin sources aggregate (plugin-title-enrichment D6): the three
		// primitive seams the api handler assembles its read-only inventory
		// from — the boot-literal catalog above, the registry module list,
		// and the per-(module, scope) gate resolution over ONE batched prefs
		// read + enrich.ResolveGates (the SAME resolution the
		// ModulePresentation closure applies; INV2: api imports neither
		// module nor enrich, so the resolution lives here).
		SourceInventory: func(_ context.Context) ([]string, map[string]string, map[string]string) {
			ids := make([]string, len(sourceCatalog))
			names := make(map[string]string, len(sourceCatalog))
			descriptions := make(map[string]string, len(sourceCatalog))
			for i, p := range sourceCatalog {
				ids[i] = p.id
				names[p.id] = p.name
				descriptions[p.id] = p.description
			}
			return ids, names, descriptions
		},
		ModuleIDs: func(context.Context) ([]string, error) {
			mods, err := reg.List()
			if err != nil {
				return nil, err
			}
			ids := make([]string, 0, len(mods))
			for _, m := range mods {
				ids = append(ids, m.ID)
			}
			return ids, nil
		},
		ModuleSources: func(ctx context.Context, moduleID string, libraryID int64) ([]string, []int, []bool, error) {
			m, err := reg.Get(moduleID)
			if err != nil {
				return nil, nil, nil, err
			}
			libraryIDs := []int64(nil)
			if libraryID != 0 {
				libraryIDs = []int64{libraryID}
			}
			prefs, err := st.ListMetadataSourcePrefs(ctx, moduleID, libraryIDs)
			if err != nil {
				return nil, nil, nil, err
			}
			gated := enrich.ResolveGates(m, prefs, libraryID)
			pids := make([]string, 0, len(gated))
			priorities := make([]int, 0, len(gated))
			enabled := make([]bool, 0, len(gated))
			for _, src := range gated {
				pids = append(pids, src.PluginID)
				priorities = append(priorities, src.Priority)
				enabled = append(enabled, src.Enabled)
			}
			return pids, priorities, enabled, nil
		},
		// Parser-attachment validation (element-pages 3.3/3.1): is pluginID
		// loaded, and which capability types does it serve? Answered from
		// loadedCaps — the capability declarations captured at each Load site —
		// so the validation set IS the loaded set (an unloaded id is unknown;
		// the closure is the anti-corruption seam that keeps api free of a
		// plugin import).
		PluginCapabilities: func(_ context.Context, pluginID string) ([]string, bool) {
			caps, ok := loadedCaps[pluginID]
			return caps, ok
		},
		// Re-enrichment admin surface (enrichment D-6/D-7): the closures are
		// built HERE in cmd/mellifera so api imports neither enrich nor
		// plugin (INV2) — the same anti-corruption seam as Status above.
		Reenrich:      newReenrichClosure(ctx, st, reg, enrichQueue, loadedCaps, sweeps),
		EnrichPreview: newEnrichPreviewClosure(st, reg),
		// Identify overlay (identify-match-override): the interactive search
		// passthrough (a live read on the request ctx) and the series
		// re-anchor (the write detaches onto the process ctx — see the
		// closure). Same INV2 seam.
		SearchSource:   newSearchClosure(enrichQueue, reg, loadedCaps),
		IdentifySeries: newIdentifyClosure(ctx, reg, enrichQueue, loadedCaps),
		// Plugin admin surfaces (plugin-admin-surfaces): the config-binding
		// flatten over the module registry (options verbatim as raw JSON —
		// api never parses config semantics, INV4) and the log tail
		// delegating to Manager.Logs — both keyed against loadedCaps, the
		// canonical loaded set, for the unknown-plugin verdict.
		PluginConfigs: newPluginConfigsClosure(reg, loadedCaps),
		PluginLogs:    newPluginLogsClosure(mgr, loadedCaps),
		// Parser wake (enrichment D-6): a successful parser attach/clear fires
		// the queue's Notify so the changed parsers re-derive at once. The
		// request-scoped ctx is substituted with the PROCESS ctx — the same
		// detachment scanDeps.Notify applies (the feeder must outlive the
		// HTTP request; SIGINT/SIGTERM cancels pool + server together).
		OnParsersChanged: func(_ context.Context, libraryID int64) {
			enrichQueue.Notify(ctx, libraryID)
		},
		// Source-gate wake (plugin-title-enrichment): a module-wide source
		// ENABLE fires the queue's Notify per affected library so the restored
		// source's namespaces re-derive without a rescan. The request-scoped
		// ctx is substituted with the PROCESS ctx — the same detachment
		// OnParsersChanged applies (the feeder must outlive the HTTP request).
		OnSourceGateChanged: func(_ context.Context, libraryID int64) {
			enrichQueue.Notify(ctx, libraryID)
		},
	})

	// Packaged-playback orchestrator (D-8/D-9/D4): the watch-driven frontier +
	// budget eviction + build-integrity sweep. Boot sweep FIRST (a restarted
	// server resumes its frontier and heals its broken builds before
	// serving), then the ≥60 s ticker for the process lifetime; both execute
	// the policies' decisions through the streams lane's EnqueuePack seam and
	// the filesystem. validate rides in as the stream Service's own
	// ValidateBuild method value (the enqueue seam's func-injection pattern);
	// the budget knob is GiB (default 32; 0 = off — see loadConfig).
	sweep := newSweep(st, cfg.streamsRoot, mediaSvc.ValidateBuild, enrichQueue.EnqueuePack, int64(cfg.orchBudgetGB)<<30)
	sweep(ctx)
	go runSweepTicker(ctx, sweep)

	// Single top-level http.Handler: web.Handler composes the api router
	// (mounted at /api/* inside web.Handler) with the token-gated /media
	// playback surface (Interface 3, ahead of the SPA fallback) + the embedded
	// SPA + Swagger surface (INV-single-handler — no second http.Server).
	// DevMode loosens the cache headers for the Vite dev proxy
	// (MELLIFERA_WEB_DEV).
	handler := web.Handler(apiHandler, web.Options{DevMode: cfg.webDev, Media: mediaSvc})

	srv := &http.Server{
		Addr:              cfg.listenAddr,
		Handler:           handler,
		ReadHeaderTimeout: readHeaderTimeout,
	}

	serveErr := make(chan error, 1)
	go func() { serveErr <- srv.ListenAndServe() }()

	select {
	case <-ctx.Done():
		slog.Info("shutting down (signal received)")
	case err := <-serveErr:
		if !errors.Is(err, http.ErrServerClosed) {
			fatalOn(err, "http server") // unexpected early exit; store.Close runs via defer
		}
		return // server already closed cleanly
	}

	shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
	defer cancel()
	logErr(srv.Shutdown(shutdownCtx), "shutdown http server")
	// INV-shutdown-order: stop accepting HTTP, THEN stop the enrich pool, THEN
	// stop plugin subprocesses. The pool stops before the plugin manager so
	// in-flight RPCs can drain against still-live subprocesses (best-effort
	// within shutdownTimeout). Stop is void: it cancels workers + waits.
	enrichQueue.Stop()
	for _, id := range pluginIDs {
		logErr(mgr.Stop(shutdownCtx, id), "stop "+id)
	}
	// store.Close runs via the deferred st.Close() in main.
}

// config is the resolved startup configuration read from the environment.
type config struct {
	dsn               string
	streamsRoot       string
	mediaSecret       []byte
	orchBudgetGB      int
	adminToken        string
	baseScannerPath   string
	serialScannerPath string
	tvParserPath      string
	imageEnricherPath string
	serialParserPath  string
	frameGrabberPath  string
	shikimoriPath     string
	listenAddr        string
	webDev            bool
	enrich            enrich.QueueConfig
}

// loadConfig reads configuration from the environment with sane MVP defaults.
// It fail-fast aborts on the one hard requirement (an admin token) and ensures
// the data directory exists so the store can open its SQLite file underneath.
func loadConfig() config {
	dataDir := envOr("MELLIFERA_DATA_DIR", "./data")
	if err := os.MkdirAll(dataDir, 0o755); err != nil {
		fatal("create data dir", err)
	}
	adminToken := os.Getenv("MELLIFERA_ADMIN_TOKEN")
	if adminToken == "" {
		slog.Error("MELLIFERA_ADMIN_TOKEN is required; refusing to serve with an empty admin token")
		os.Exit(1)
	}
	return config{
		dsn: filepath.Join(dataDir, "mellifera.db"),
		// Packaged-playback: the artifact root inside the server's own data
		// space (never a library directory) and the media-token HMAC secret
		// (D-6 — distinct from the admin token by construction: it is a
		// separate env var, and an unset one falls back to a fresh random
		// 32-byte secret, never to the admin credential). The secret is never
		// logged.
		streamsRoot: filepath.Join(dataDir, "streams"),
		mediaSecret: mediaSecret(),
		// Packaged-playback budget knob (D-9): the artifact budget in GiB,
		// default 32; `0` disables the cap entirely. Non-positive reads as
		// off (the orchestrator's Evictions contract), so the knob can never
		// accidentally evict everything.
		orchBudgetGB:      envInt("MELLIFERA_ORCH_BUDGET_GB", 32),
		adminToken:        adminToken,
		baseScannerPath:   envOr("MELLIFERA_BASE_SCANNER", "bin/base-scanner"),
		serialScannerPath: envOr("MELLIFERA_SERIAL_SCANNER", "bin/serial-scanner"),
		tvParserPath:      envOr("MELLIFERA_TV_PARSER", "bin/tv-parser"),
		imageEnricherPath: envOr("MELLIFERA_IMAGE_ENRICHER", "bin/image-enricher"),
		serialParserPath:  envOr("MELLIFERA_SERIAL_PARSER", "bin/serial-parser"),
		frameGrabberPath:  envOr("MELLIFERA_FRAME_GRABBER", "bin/frame-grabber"),
		shikimoriPath:     envOr("MELLIFERA_SHIKIMORI", "bin/shikimori"),
		listenAddr:        envOr("MELLIFERA_LISTEN", "127.0.0.1:8080"),
		// webDev=true loosens the SPA cache headers (no-cache everywhere) so the
		// Vite dev proxy :5173 can hot-reload alongside this server. Default
		// false (production: immutable /assets/* + no-cache index.html).
		webDev: envBool("MELLIFERA_WEB_DEV", false),
		// Async enrich queue knobs (arch §4.4). Every field has a §4.4 default;
		// a missing/empty/malformed value falls back to it + logs a warning
		// (INV-env-defaults: startup never aborts on an enrich knob). Only the
		// admin token remains fail-fast.
		enrich: enrich.QueueConfig{
			Workers:       envInt("MELLIFERA_ENRICH_WORKERS", 4),
			MaxAttempts:   envInt("MELLIFERA_ENRICH_MAX_ATTEMPTS", 3),
			LeaseTTL:      envDuration("MELLIFERA_ENRICH_LEASE_TTL", 60*time.Second),
			Backoff:       envDuration("MELLIFERA_ENRICH_BACKOFF", 2*time.Second),
			ExhaustedCool: envDuration("MELLIFERA_ENRICH_EXHAUSTED_COOL", 7*24*time.Hour),
			NoDataCool:    envDuration("MELLIFERA_ENRICH_NODATA_COOL", 30*24*time.Hour),
			CoolCap:       envDuration("MELLIFERA_ENRICH_COOL_CAP", 365*24*time.Hour),
		},
	}
}

// envInt reads an integer env var, falling back to def (and logging a warning)
// when it is unset/empty/malformed. Used for the enrich knobs (INV-env-defaults).
func envInt(key string, def int) int {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		slog.Warn("invalid int env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return n
}

// envDuration reads a duration env var (time.ParseDuration syntax), falling back
// to def (and logging a warning) when unset/empty/malformed (INV-env-defaults).
func envDuration(key string, def time.Duration) time.Duration {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	d, err := time.ParseDuration(v)
	if err != nil {
		slog.Warn("invalid duration env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return d
}

// envOr returns the named env var or def when it is unset/empty.
func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

// mediaSecret resolves the media-token HMAC secret: MELLIFERA_MEDIA_SECRET
// (hex) when set, else a fresh random 32-byte secret. A random fallback means
// outstanding media tokens die at restart (they are 4 h playback grants, not
// identities — re-fetching the descriptor re-mints). Never logged; a
// malformed hex value is fatal (a silently ignored secret would look healthy
// while every token verify fails).
func mediaSecret() []byte {
	if v := os.Getenv("MELLIFERA_MEDIA_SECRET"); v != "" {
		b, err := hex.DecodeString(v)
		if err != nil || len(b) == 0 {
			fatal("parse MELLIFERA_MEDIA_SECRET", errors.New("must be non-empty hex"))
		}
		return b
	}
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		fatal("generate media secret", err)
	}
	return b
}

// copyStrings clones a string slice so a closure return can never alias its
// source — the module registry's cached config state is copied defensively at
// the api seam (the same rule internal/module's own accessors follow).
func copyStrings(src []string) []string {
	out := make([]string, len(src))
	copy(out, src)
	return out
}

// originalResolver builds the stream Service's direct-floor resolver over the
// store: the item's parsed.absolute_path (the stamp scan assembles) — the
// same single file-location channel the enrich chain reads. ok is false for
// any absent/unreadable stamp; the /media handler answers 404.
func originalResolver(st *store.Store) func(ctx context.Context, itemID string) (string, bool) {
	return func(ctx context.Context, itemID string) (string, bool) {
		row, err := st.GetItem(ctx, itemID)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return "", false
			}
			slog.Warn("media: original lookup failed", "item", itemID, "error", err)
			return "", false
		}
		var doc struct {
			Parsed struct {
				AbsolutePath string `json:"absolute_path"`
			} `json:"parsed"`
		}
		if err := json.Unmarshal(row.Document, &doc); err != nil {
			return "", false
		}
		return doc.Parsed.AbsolutePath, doc.Parsed.AbsolutePath != ""
	}
}

// sweepGuard is the per-library whole-sweep in-flight flag the Reenrich
// closure owns (enrichment design Interfaces): a second concurrent
// whole-library sweep for one library is refused with api.ErrRefreshInFlight
// (→ 409 at the handler). Per-row refreshes never touch the guard.
type sweepGuard struct {
	mu       sync.Mutex
	inFlight map[int64]bool
}

// begin claims the library's whole-sweep slot, reporting whether the claim
// succeeded (false = a sweep is already in flight).
func (g *sweepGuard) begin(libraryID int64) bool {
	g.mu.Lock()
	defer g.mu.Unlock()
	if g.inFlight[libraryID] {
		return false
	}
	g.inFlight[libraryID] = true
	return true
}

// finish releases the library's whole-sweep slot.
func (g *sweepGuard) finish(libraryID int64) {
	g.mu.Lock()
	defer g.mu.Unlock()
	delete(g.inFlight, libraryID)
}

// newReenrichClosure builds the api Deps.Reenrich seam (enrichment design
// Interfaces): it translates the operator's refresh request into
// Queue.ReenrichSource and owns every outcome-translation input —
// unknown-plugin (the id is not a loaded plugin, or no module config binds it
// as a metadata_source) and unknown-rows (a row id naming no item/series row
// of the library) are rejected with their api sentinels BEFORE any strip; a
// whole-library sweep (row_ids omitted) claims the per-library in-flight slot
// for the sweep's duration, while a per-row refresh bypasses the guard
// entirely. Queued = the rows the sweep scoped = stripped + deferred
// (Queue.ReenrichSource's counting invariant). procCtx is the PROCESS ctx
// ReenrichSource rides: the closure discards the request-scoped ctx at its
// boundary — the same detachment scanDeps.Notify applies (the queue's feeder
// must outlive the HTTP request).
func newReenrichClosure(
	procCtx context.Context, st *store.Store, reg *module.Registry, q *enrich.Queue,
	loadedPlugins map[string][]string, sweeps *sweepGuard,
) func(context.Context, int64, string, []string) (api.ReenrichResult, error) {
	return func(_ context.Context, libraryID int64, pluginID string, rowIDs []string) (api.ReenrichResult, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded || !hasMetadataBinding(reg, pluginID) {
			return api.ReenrichResult{}, fmt.Errorf("refresh %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		if len(rowIDs) == 0 { // whole-library sweep: one per library at a time
			if !sweeps.begin(libraryID) {
				return api.ReenrichResult{}, fmt.Errorf("library %d refresh %q: %w", libraryID, pluginID, api.ErrRefreshInFlight)
			}
			defer sweeps.finish(libraryID)
		} else {
			// Pre-check row identity so a 404 never strips anything (the
			// admin-API spec: unknown rows are rejected with neither
			// triggering a strip).
			for _, id := range rowIDs {
				ok, err := rowInLibrary(procCtx, st, libraryID, id)
				if err != nil {
					return api.ReenrichResult{}, err
				}
				if !ok {
					return api.ReenrichResult{}, fmt.Errorf("refresh %q row %q: %w", pluginID, id, api.ErrUnknownRows)
				}
			}
		}
		// The request-scoped ctx is substituted with the PROCESS ctx — the
		// same detachment scanDeps.Notify applies (the feeder must outlive
		// the HTTP request): ReenrichSource ends in a queue Notify whose
		// feeder selects on the ctx it is handed, so the cancelled request
		// ctx would abort it the moment the 202 is written and the stripped
		// rows would stay pending forever (SIGINT/SIGTERM cancels pool +
		// server together).
		stripped, deferred, err := q.ReenrichSource(procCtx, libraryID, pluginID, rowIDs...)
		if err != nil {
			return api.ReenrichResult{}, err
		}
		return api.ReenrichResult{Queued: stripped + deferred, Stripped: stripped, Deferred: deferred}, nil
	}
}

// rowInLibrary reports whether rowID names an item or series row of the given
// library. A row of a DIFFERENT library reports false — row ids are opaque
// strings, so the library binding is the identity check. Mirrors the api
// package's resolveFailureRow lookup order (items, then series).
func rowInLibrary(ctx context.Context, st *store.Store, libraryID int64, rowID string) (bool, error) {
	it, err := st.GetItem(ctx, rowID)
	switch {
	case err == nil:
		return it.LibraryID == libraryID, nil
	case !errors.Is(err, sql.ErrNoRows):
		return false, err
	}
	sr, err := st.GetSeries(ctx, rowID)
	switch {
	case err == nil:
		return sr.LibraryID == libraryID, nil
	case !errors.Is(err, sql.ErrNoRows):
		return false, err
	}
	return false, nil
}

// hasMetadataBinding reports whether any module config binds pluginID as a
// metadata_source. The Registry half of unknown-plugin detection: a scanner
// plugin, or an id no module binds, is not refreshable (its sweep would
// always be vacuous).
func hasMetadataBinding(reg *module.Registry, pluginID string) bool {
	mods, err := reg.List()
	if err != nil {
		return false
	}
	for _, m := range mods {
		for _, src := range m.MetadataSources {
			if src.PluginID == pluginID {
				return true
			}
		}
	}
	return false
}

// newSearchClosure builds the api Deps.SearchSource seam (identify-match-
// override): the interactive search is a live read against the source's own
// budget — the request ctx rides, because nothing needs to outlive the answer
// (unlike the re-anchoring identify, a search notifies nothing). Validation
// mirrors newReenrichClosure: an unknown plugin (not loaded, or no module
// binds it as a metadata_source) is rejected with the api sentinel BEFORE the
// queue is asked, and the SDK's unsupported-search sentinel is re-wrapped so
// the handler's errors.Is maps it to 400 search_unsupported.
func newSearchClosure(
	q *enrich.Queue, reg *module.Registry, loadedPlugins map[string][]string,
) func(context.Context, string, string, string) ([]map[string]any, error) {
	return func(ctx context.Context, pluginID, query, kind string) ([]map[string]any, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded || !hasMetadataBinding(reg, pluginID) {
			return nil, fmt.Errorf("search %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		cands, err := q.SearchSource(ctx, pluginID, query, kind)
		if errors.Is(err, sdk.ErrSearchUnsupported) {
			return nil, fmt.Errorf("search %q: %w", pluginID, api.ErrSearchUnsupported)
		}
		return cands, err
	}
}

// newIdentifyClosure builds the api Deps.IdentifySeries seam (identify-match-
// override): the operator's picked anchor rides into Queue.IdentifySeries on
// the PROCESS ctx — the identify write ends in a queue Notify whose feeder
// must outlive the HTTP request, so the request-scoped ctx is discarded at
// this boundary (the newReenrichClosure detachment). Unknown-plugin
// validation runs BEFORE any write (the spec: nothing is written on the
// error paths); an unknown series surfaces as the store's sql.ErrNoRows,
// preserved for the handler's 404.
func newIdentifyClosure(
	procCtx context.Context, reg *module.Registry, q *enrich.Queue,
	loadedPlugins map[string][]string,
) func(context.Context, string, string, string) (bool, int, int, error) {
	return func(_ context.Context, seriesID, pluginID, externalID string) (bool, int, int, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded || !hasMetadataBinding(reg, pluginID) {
			return false, 0, 0, fmt.Errorf("identify %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		return q.IdentifySeries(procCtx, seriesID, pluginID, externalID)
	}
}

// previewBatch is the pagination width for the preview closure's QueryItems
// scan (the queue's deriveBatch width).
const previewBatch = 1000

// newEnrichPreviewClosure builds the api Deps.EnrichPreview seam (enrichment
// D-7): the per-plugin drift picture for one library, computed on demand over
// the stored documents and the ledger — matches (rows carrying the plugin's
// sources.<pluginID> namespace), pending (rows whose (row, plugin) pair the
// derivation predicate still owes work: a queueable module binding, namespace
// absent, not in ledger cooldown), cooling (rows with a within-cooldown ledger
// row for the plugin), versions (a histogram over the _provenance entries the
// plugin authored, keyed by plugin_version). Drift is computed, never stored;
// the predicates are restated cmd-side to mirror the queue's pendingSources +
// inCooldown semantics, so the numbers an operator consents to are the ones a
// sweep would act on.
func newEnrichPreviewClosure(st *store.Store, reg *module.Registry) func(context.Context, int64, string) (api.EnrichPreview, error) {
	return func(ctx context.Context, libraryID int64, pluginID string) (api.EnrichPreview, error) {
		failures, err := st.ListFailures(ctx)
		if err != nil {
			return api.EnrichPreview{}, fmt.Errorf("preview: list ledger: %w", err)
		}
		nowt := time.Now()
		cooling := make(map[string]bool)
		for _, fr := range failures {
			if fr.PluginID == pluginID && fr.NextEligibleAt.After(nowt) {
				cooling[fr.ItemID] = true
			}
		}
		pv := api.EnrichPreview{PluginID: pluginID, Versions: map[string]int{}}
		account := func(rowID, moduleID string, docRaw json.RawMessage) {
			var doc map[string]any
			if err := json.Unmarshal(docRaw, &doc); err != nil {
				return // soft: an unreadable document contributes nothing (decodeDoc's rule)
			}
			namespaced := hasSourceNamespace(doc, pluginID)
			if namespaced {
				pv.Matches++
			}
			if queueableBinding(reg, moduleID, pluginID) && !namespaced && !cooling[rowID] {
				pv.Pending++
			}
			prov, ok := doc["_provenance"].(map[string]any)
			if !ok {
				return
			}
			for _, entry := range prov {
				e, ok := entry.(map[string]any)
				if !ok {
					continue
				}
				if pid, _ := e["plugin_id"].(string); pid == pluginID {
					v, _ := e["plugin_version"].(string)
					pv.Versions[v]++
				}
			}
		}
		for offset := 0; ; offset += previewBatch {
			batch, err := st.QueryItems(ctx, libraryID, "", previewBatch, offset)
			if err != nil {
				return api.EnrichPreview{}, fmt.Errorf("preview: query items lib %d: %w", libraryID, err)
			}
			for _, it := range batch {
				account(it.ID, it.ModuleID, it.Document)
			}
			if len(batch) < previewBatch {
				break
			}
		}
		seriesRows, err := st.QuerySeries(ctx, libraryID, "")
		if err != nil {
			return api.EnrichPreview{}, fmt.Errorf("preview: query series lib %d: %w", libraryID, err)
		}
		for _, sr := range seriesRows {
			account(sr.ID, sr.ModuleID, sr.Document)
		}
		return pv, nil
	}
}

// hasSourceNamespace reports whether the document carries the plugin's
// sources.<pluginID> namespace — the enrich chain's hasNamespace shape,
// restated cmd-side (the enrich original is unexported).
func hasSourceNamespace(doc map[string]any, pluginID string) bool {
	sources, ok := doc["sources"].(map[string]any)
	if !ok {
		return false
	}
	_, exists := sources[pluginID]
	return exists
}

// queueableBinding reports whether moduleID's config binds pluginID as a
// RUNNABLE metadata source — the queue's D-Q1 predicate (Enabled and not
// CLIENT-only) restated cmd-side; an unresolvable module or an unbound plugin
// is not derivable.
func queueableBinding(reg *module.Registry, moduleID, pluginID string) bool {
	mod, err := reg.Get(moduleID)
	if err != nil {
		return false
	}
	for _, src := range mod.MetadataSources {
		if src.PluginID == pluginID {
			return src.Enabled && src.AuthMode != "CLIENT"
		}
	}
	return false
}

// Binding-kind literals of the plugin-config rows (plugin-admin-surfaces):
// module.Registry's two binding slots, flattened to the wire vocabulary the
// api handler renders. Restated here because the wire DTOs are api-unexported
// (the export budget) — INV4 keeps them from sharing a type.
const (
	bindingKindScanner  = "scanner"
	bindingKindMetadata = "metadata"
)

// pluginConfigRows accumulates one plugin's binding rows as parallel slices —
// the Deps.PluginConfigs closure's primitive return shape (the
// sourceResolution precedent; the api export budget keeps the wire DTOs
// unexported, so no struct crosses the seam).
type pluginConfigRows struct {
	moduleIDs, kinds, authModes, displayFields, options []string
	priorities                                          []int
	enabled                                             []bool
}

func (r *pluginConfigRows) add(moduleID, kind string, priority int, enabled bool, authMode, displayFields, options string) {
	r.moduleIDs = append(r.moduleIDs, moduleID)
	r.kinds = append(r.kinds, kind)
	r.priorities = append(r.priorities, priority)
	r.enabled = append(r.enabled, enabled)
	r.authModes = append(r.authModes, authMode)
	r.displayFields = append(r.displayFields, displayFields)
	r.options = append(r.options, options)
}

// newPluginConfigsClosure builds the api Deps.PluginConfigs seam
// (plugin-admin-surfaces D4): one row per module binding of pluginID across
// the registry — the scanner slot (kind "scanner"), then each metadata source
// (kind "metadata") in config order. Options and display_fields ride as RAW
// JSON strings embedded verbatim by the handler — api never parses config
// semantics (INV4). An id outside loadedPlugins is unknown (wrapping
// api.ErrUnknownPlugin, the refresh rule); a loaded plugin with no bindings
// returns empty rows.
func newPluginConfigsClosure(reg *module.Registry, loadedPlugins map[string][]string) func(context.Context, string) ([]string, []string, []int, []bool, []string, []string, []string, error) {
	return func(_ context.Context, pluginID string) ([]string, []string, []int, []bool, []string, []string, []string, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded {
			return nil, nil, nil, nil, nil, nil, nil,
				fmt.Errorf("plugin configs %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		mods, err := reg.List()
		if err != nil {
			return nil, nil, nil, nil, nil, nil, nil, err
		}
		rows := &pluginConfigRows{}
		for _, m := range mods {
			if m.Scanner.PluginID == pluginID {
				rows.add(m.ID, bindingKindScanner, 0, false, "", "",
					string(m.Scanner.Options))
			}
			for _, src := range m.MetadataSources {
				if src.PluginID != pluginID {
					continue
				}
				rows.add(m.ID, bindingKindMetadata, src.Priority, src.Enabled,
					src.AuthMode, rawStringsJSON(src.DisplayFields), string(src.Options))
			}
		}
		return rows.moduleIDs, rows.kinds, rows.priorities, rows.enabled,
			rows.authModes, rows.displayFields, rows.options, nil
	}
}

// rawStringsJSON flattens a binding's display_fields declaration to a raw
// JSON string for the verbatim-embedding seam; undeclared fields ride as ""
// (omitted on the wire). json.Marshal of a []string cannot fail.
func rawStringsJSON(fields []string) string {
	if len(fields) == 0 {
		return ""
	}
	b, err := json.Marshal(fields)
	if err != nil {
		return ""
	}
	return string(b)
}

// newPluginLogsClosure builds the api Deps.PluginLogs seam (plugin-admin-
// surfaces D3): pure delegation over Manager.Logs — the host-captured stderr
// tail, oldest line first. loadedPlugins is the unknown-plugin gate (the
// canonical loaded set): an id outside it wraps api.ErrUnknownPlugin (→ 400
// at the handler); a Manager error on a known id is a real failure (→ 500).
func newPluginLogsClosure(mgr *plugin.Manager, loadedPlugins map[string][]string) func(context.Context, string) ([]string, error) {
	return func(_ context.Context, pluginID string) ([]string, error) {
		if _, loaded := loadedPlugins[pluginID]; !loaded {
			return nil, fmt.Errorf("plugin logs %q: %w", pluginID, api.ErrUnknownPlugin)
		}
		lines, err := mgr.Logs(pluginID)
		if err != nil {
			return nil, fmt.Errorf("plugin logs %q: %w", pluginID, err)
		}
		return lines, nil
	}
}

// envBool reads a boolean env var (1/t/T/true/TRUE/True → true; everything else
// → def). It mirrors strconv.ParseBool's accepted set; an unset/empty/invalid
// value falls back to def (INV-env-defaults: startup never aborts on a webDev
// knob). Used for MELLIFERA_WEB_DEV.
func envBool(key string, def bool) bool {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	b, err := strconv.ParseBool(v)
	if err != nil {
		slog.Warn("invalid bool env var; using default", "key", key, "value", v, "default", def, "error", err)
		return def
	}
	return b
}

// fatalOn aborts the process if err is non-nil. Used for startup wiring, where a
// failure means the app cannot run.
func fatalOn(err error, label string) {
	if err != nil {
		fatal(label, err)
	}
}

func fatal(label string, err error) {
	slog.Error(label, "error", err)
	os.Exit(1)
}

// logErr logs a non-nil error without aborting. Used in the graceful-shutdown
// path so each step gets a chance to run even if an earlier one errored.
func logErr(err error, label string) {
	if err != nil {
		slog.Error(label, "error", err)
	}
}
